#!/usr/bin/env python3
"""
Convert ponyfill.es5.js → web-streams-polyfill_js.h with a single
escaped C string literal `web_streams_polyfill_js`.

gcc handles ~71 KB single-line literals without issue (verified), so
no chunking needed.  Re-run after upgrading the polyfill bundle.

Usage:  python3 gen_header.py
"""
import os, sys, re

HERE = os.path.dirname(os.path.abspath(__file__))
SRC  = os.path.join(HERE, 'ponyfill.es5.js')
OUT  = os.path.join(HERE, 'web-streams-polyfill_js.h')

data = open(SRC, 'rb').read().decode('latin-1')

# C string literal escaping
escaped = (data
    .replace('\\', '\\\\')
    .replace('"',  '\\"')
    .replace('\r', '')
    .replace('\n', '\\n')
    .replace('\t', '\\t'))
# Trigraph protection (?? sequences) per C99 — even though gcc disables
# trigraphs by default these days, this keeps us forward-portable
escaped = re.sub(r'\?\?', '?\\?', escaped)

header = (
    '/* AUTO-GENERATED by extern/web-streams-polyfill/gen_header.py.\n'
    ' * Do not edit by hand — re-run the generator after updating\n'
    ' * ponyfill.es5.js.\n'
    ' *\n'
    ' * Source: web-streams-polyfill v4.3.0, ES5 ponyfill (UMD).\n'
    ' * License: MIT (see ./LICENSE).\n'
    ' */\n'
    '#ifndef RP_WEB_STREAMS_POLYFILL_JS_H\n'
    '#define RP_WEB_STREAMS_POLYFILL_JS_H\n'
    '\n'
    'static const char *web_streams_polyfill_js =\n'
    '    "' + escaped + '";\n'
    '\n'
    '#endif\n'
)

with open(OUT, 'w') as f:
    f.write(header)

print(f"Generated {OUT}: {len(escaped)} escaped chars (source {len(data)})")
